    // ---- flag values on a representative set of preconditioners ----

    [Test]
    public void IdentityFlagsAreSpdAndConstant()
    {
        var M = new doubleIdentityPreconditioner();
        Assert.IsTrue(M.IsSpd);
        Assert.IsTrue(M.IsConstant);
    }

